ALTER TABLE "runs" DROP CONSTRAINT "run_accounting_version_valid";--> statement-breakpoint
ALTER TABLE "provider_calls" DROP CONSTRAINT "provider_cap_valid";--> statement-breakpoint
ALTER TABLE "runs" ADD CONSTRAINT "run_accounting_version_valid" CHECK ("runs"."accounting_version" IN (0,1,2,3));--> statement-breakpoint
ALTER TABLE "provider_calls" ADD CONSTRAINT "provider_cap_valid" CHECK ("provider_calls"."cap_micro_usd" > 0 AND "provider_calls"."cap_micro_usd" = CASE WHEN "provider_calls"."budget_version"=1 THEN CASE "provider_calls"."stage" WHEN 'PLANNER' THEN 2000 WHEN 'INPUT_SAFETY' THEN 5000 WHEN 'QUERY_SAFETY' THEN 5000 WHEN 'SEARCH' THEN 8000 WHEN 'EVIDENCE_SAFETY' THEN 5000 WHEN 'ANSWER' THEN 20000 WHEN 'OUTPUT_SAFETY' THEN 5000 ELSE -1 END WHEN "provider_calls"."budget_version" IN (2,3) THEN CASE "provider_calls"."stage" WHEN 'PLANNER' THEN 2000 WHEN 'INPUT_SAFETY' THEN 2250 WHEN 'QUERY_SAFETY' THEN 2250 WHEN 'QUERY_SECOND' THEN 2250 WHEN 'SEARCH' THEN 8000 WHEN 'SEARCH_SECOND' THEN 8000 WHEN 'EXTRACT' THEN 8000 WHEN 'EVIDENCE_SAFETY' THEN 2250 WHEN 'ANSWER' THEN CASE WHEN "provider_calls"."budget_version"=3 THEN 48000 ELSE 12500 END WHEN 'OUTPUT_SAFETY' THEN 2250 ELSE -1 END ELSE -1 END);